23	// Bundle represents an in-memory OKF bundle.
24	type Bundle struct {
25		RootPath     string              `json:"root_path"`
26		DeclaredVer  string              `json:"declared_version,omitempty"` // e.g. "0.2" from root index.md
27		Scopes       []Scope             `json:"scopes,omitempty"`           // optional allowed memory scopes from root index.md
28		Concepts     map[string]*Concept `json:"concepts"`                   // concept ID -> Concept
29		Indexes      map[string]string   `json:"indexes"`                    // relPath -> raw content
30		LogContent   string              `json:"log_content,omitempty"`
31		Graph        map[string][]string `json:"graph"`         // concept ID -> outbound concept IDs
32		InboundGraph map[string][]string `json:"inbound_graph"` // concept ID -> inbound concept IDs
33		BrokenLinks  []BrokenLink        `json:"broken_links,omitempty"`
34		Orphans      []string            `json:"orphans,omitempty"`
35	}
36	
37	// AllowedScope reports whether the given scope is permitted by this bundle's configuration.
38	// If no scopes were explicitly configured in root index.md, all scopes are allowed.
39	func (b *Bundle) AllowedScope(s Scope) bool {
40		if b == nil || len(b.Scopes) == 0 {
41			return true
42		}
43		for _, allowed := range b.Scopes {
44			if allowed == s {
45				return true
46			}
47		}
48		return false
49	}
