51	// BrokenLink records a link from a concept to a non-existent target or reserved file.
52	type BrokenLink struct {
53		SourceConcept string `json:"source_concept"`
54		TargetHref    string `json:"target_href"`
55		Reason        string `json:"reason"`
56	}
