175	// ensureRootWithinParent rejects a bundle root whose symlink target lies outside the directory containing the link.
176	func ensureRootWithinParent(root, realRoot string) error {
177		absRoot, err := filepath.Abs(root)
178		if err != nil {
179			return fmt.Errorf("failed to get absolute path of bundle root: %w", err)
180		}
181		if _, err := ensureWithinRoot(filepath.Dir(absRoot), realRoot); err != nil {
182			return fmt.Errorf("bundle root %q resolves outside its parent directory: %w", root, err)
183		}
184		return nil
185	}
