296	func loadBundle(root string, trustedRoot bool) (*Bundle, error) {
297		walkRoot, bundlePath, err := resolveBundleRoot(root, trustedRoot)
298		if err != nil {
299			return nil, err
300		}
301	
302		b := &Bundle{
303			RootPath:     bundlePath,
304			Concepts:     make(map[string]*Concept),
305			Indexes:      make(map[string]string),
306			Graph:        make(map[string][]string),
307			InboundGraph: make(map[string][]string),
308		}
309	
310		// 1. Walk directory and collect files
311		err = filepath.WalkDir(walkRoot, func(path string, d fs.DirEntry, walkErr error) error {
312			if walkErr != nil {
313				return walkErr
314			}
315			if d.IsDir() {
316				if path == walkRoot {
317					return nil
318				}
319				rel, err := filepath.Rel(walkRoot, path)
320				if err == nil && (rel == "." || rel == "") {
321					return nil
322				}
323				name := d.Name()
324				if strings.HasPrefix(name, ".") || name == "node_modules" {
325					return filepath.SkipDir
326				}
327				return nil
328			}
329	
330			name := d.Name()
331			if strings.HasPrefix(name, ".") || !strings.HasSuffix(name, ".md") {
332				return nil
333			}
334	
335			rel, err := filepath.Rel(walkRoot, path)
336			if err != nil {
337				return err
338			}
339			rel = filepath.ToSlash(rel)
340	
341			// Root AGENTS.md is the agent governance layer (DMAA L1), not an OKF concept
342			if strings.EqualFold(rel, "AGENTS.md") {
343				return nil
344			}
345	
346			// Security: prevent symlink following outside bundle directory
347			if d.Type()&fs.ModeSymlink != 0 {
348				realTarget, err := ensureWithinRoot(walkRoot, path)
349				if err != nil {
350					return err
351				}
352				fi, err := os.Stat(realTarget)
353				if err != nil {
354					return fmt.Errorf("cannot stat symlink target %q: %w", rel, err)
355				}
356				if fi.IsDir() {
357					return fmt.Errorf("symlink %q points to a directory, not a markdown file", rel)
358				}
359				if !strings.HasSuffix(strings.ToLower(realTarget), ".md") {
360					return fmt.Errorf("symlink %q must point to a markdown (.md) file", rel)
361				}
362			}
363	
364			// #nosec G122,G304 -- path is strictly within bundle root and symlinks are resolved via ensureWithinRoot
365			data, err := os.ReadFile(path)
366			if err != nil {
367				return err
368			}
369			content := string(data)
370	
371			if name == "index.md" {
372				b.Indexes[rel] = content
373				if rel == "index.md" {
374					fm, _, hasFM := ExtractFrontmatter(content)
375					if hasFM {
376						ver, scopes, err := parseRootIndexFrontmatter(fm)
377						if err != nil {
378							return err
379						}
380						b.DeclaredVer = ver
381						b.Scopes = scopes
382					}
383				}
384				return nil
385			}
386	
387			if name == "log.md" {
388				if rel == "log.md" {
389					b.LogContent = content
390				}
391				return nil
392			}
393	
394			// Concept document
395			c, parseErr := ParseConcept(rel, content)
396			if parseErr != nil {
397				// Save stub concept with raw content for validator reporting
398				id := strings.TrimSuffix(rel, ".md")
399				b.Concepts[id] = &Concept{
400					ID:         id,
401					Path:       rel,
402					RawContent: content,
403					sourceHash: hashConceptContent(content),
404				}
405			} else {
406				c.sourceHash = hashConceptContent(content)
407				b.Concepts[c.ID] = c
408			}
409			return nil
410		})
411		if err != nil {
412			return nil, err
413		}
414	
415		// 2. Build link graph & check connectivity
416		b.buildGraph()
417		return b, nil
418	}
