19	const DefaultRegistryURL = "https://registry.okf-memory.dev"
20	
21	type BundleManifest struct {
22		ID          string `json:"id"`
23		Version     string `json:"version"`
24		Hash        string `json:"hash"`
25		DownloadURL string `json:"download_url"`
26	}
27	
28	type Client struct {
29		BaseURL    string
30		HTTPClient *http.Client
31	}
32	
33	func NewClient(baseURL string) *Client {
34		if baseURL == "" {
35			baseURL = DefaultRegistryURL
36		}
37		return &Client{
38			BaseURL: strings.TrimRight(baseURL, "/"),
39			HTTPClient: &http.Client{
40				Timeout: 30 * time.Second,
41			},
42		}
43	}
44	
45	func (c *Client) Resolve(slugOrURL string) (*BundleManifest, error) {
46		if strings.HasPrefix(slugOrURL, "github.com/") || strings.HasPrefix(slugOrURL, "https://") {
47			return c.resolveGitURL(slugOrURL)
48		}
49	
50		cleanSlug := strings.Trim(strings.TrimSpace(slugOrURL), "/")
51		target := strings.TrimPrefix(cleanSlug, "@")
52	
53		var slug, version string
54		if idx := strings.Index(target, "@"); idx != -1 {
55			slug = target[:idx]
56			version = target[idx+1:]
57		} else {
58			slug = target
59		}
60	
61		var candidateEndpoints []string
62		if version != "" {
63			candidateEndpoints = append(candidateEndpoints,
64				fmt.Sprintf("%s/bundles/%s-%s.json", c.BaseURL, slug, version),
65				fmt.Sprintf("%s/bundles/@%s-%s.json", c.BaseURL, slug, version),
66			)
67		} else {
68			candidateEndpoints = append(candidateEndpoints,
69				fmt.Sprintf("%s/bundles/%s.json", c.BaseURL, slug),
70				fmt.Sprintf("%s/bundles/@%s.json", c.BaseURL, slug),
71			)
72		}
73	
74		fetchManifest := func(endpoint string) (*BundleManifest, int, error) {
75			req, err := http.NewRequest("GET", endpoint, nil)
76			if err != nil {
77				return nil, 0, err
78			}
79			req.Header.Set("User-Agent", "okf-agent-memory-cli")
80			resp, err := c.HTTPClient.Do(req)
81			if err != nil {
82				return nil, 0, err
83			}
84			defer func() { _ = resp.Body.Close() }()
85	
86			if resp.StatusCode == http.StatusOK {
87				var m BundleManifest
88				if err := json.NewDecoder(resp.Body).Decode(&m); err != nil {
89					return nil, resp.StatusCode, fmt.Errorf("malformed registry manifest: %w", err)
90				}
91				if err := ValidateBundleID(m.ID); err != nil {
92					return nil, resp.StatusCode, fmt.Errorf("refusing registry manifest %s: %w", endpoint, err)
93				}
94				if strings.HasPrefix(m.DownloadURL, "/") {
95					m.DownloadURL = c.BaseURL + m.DownloadURL
96				}
97				return &m, http.StatusOK, nil
98			}
99			return nil, resp.StatusCode, nil
100		}
101	
102		for _, ep := range candidateEndpoints {
103			m, status, err := fetchManifest(ep)
104			if err != nil {
105				return nil, err
106			}
107			if status == http.StatusOK && m != nil {
108				return m, nil
109			}
110		}
111	
112		// If versioned endpoint was 404, fallback to base bundles/<slug>.json
113		if version != "" {
114			baseCandidates := []string{
115				fmt.Sprintf("%s/bundles/%s.json", c.BaseURL, slug),
116				fmt.Sprintf("%s/bundles/@%s.json", c.BaseURL, slug),
117			}
118			for _, baseEp := range baseCandidates {
119				m, status, err := fetchManifest(baseEp)
120				if err != nil {
121					return nil, err
122				}
123				if status == http.StatusOK && m != nil {
124					if strings.TrimPrefix(m.Version, "v") != strings.TrimPrefix(version, "v") {
125						return nil, fmt.Errorf("bundle %q version %s not found in registry (latest is %s)", slug, version, m.Version)
126					}
127					return m, nil
128				}
129			}
130			return nil, fmt.Errorf("bundle %q (version %s) not found in registry %s", slug, version, c.BaseURL)
131		}
132	
133		return nil, fmt.Errorf("bundle %q not found in registry %s", cleanSlug, c.BaseURL)
134	}
135	
136	func (c *Client) resolveGitURL(rawURL string) (*BundleManifest, error) {
137		tag := ""
138		if idx := strings.Index(rawURL, "@"); idx != -1 {
139			tag = rawURL[idx+1:]
140			rawURL = rawURL[:idx]
141		}
142	
143		parsedURL := rawURL
144		if !strings.HasPrefix(parsedURL, "http://") && !strings.HasPrefix(parsedURL, "https://") {
145			parsedURL = "https://" + parsedURL
146		}
147		u, err := url.Parse(parsedURL)
148		if err != nil {
149			return nil, fmt.Errorf("invalid Git URL: %w", err)
150		}
151	
152		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
153		if len(parts) < 2 {
154			return nil, fmt.Errorf("git URL must follow github.com/owner/repo format")
155		}
156		owner, repo := parts[0], parts[1]
157		id := fmt.Sprintf("%s/%s", owner, repo)
158		if err := ValidateBundleID(id); err != nil {
159			return nil, fmt.Errorf("invalid Git URL %q: %w", rawURL, err)
160		}
161	
162		var archiveURL string
163		version := tag
164		if tag != "" {
165			archiveURL = fmt.Sprintf("https://github.com/%s/%s/archive/refs/tags/%s.tar.gz", owner, repo, tag)
166		} else {
167			version = "main"
168			archiveURL = fmt.Sprintf("https://github.com/%s/%s/archive/refs/heads/main.tar.gz", owner, repo)
169		}
170	
171		return &BundleManifest{
172			ID:          id,
173			Version:     version,
174			Hash:        "",
175			DownloadURL: archiveURL,
176		}, nil
177	}
